insert into public.fi_tarefas_escrita (id,tipo,titulo,instrucao_pt,modelo_en,pontos,nivel,ordem) values ($q$e4$q$,$q$work$q$,$q$Apresentar-se ao time$q$,$q$Escreva 4 ou 5 frases se apresentando ao novo time: nome, cargo, experiência e o que espera do trabalho.$q$,$q$Hi everyone, my name is Sofia and I'm the new financial analyst. I have six years of experience in banking. In my last job, I worked with budgets and reports. I'm very happy to join the team, and I hope to learn a lot from you. Please feel free to ask me anything.$q$,$q$[{"pt":"Disse o nome","kw":["my name","i'm","i am"]},{"pt":"Disse o cargo","kw":["analyst","manager","position","job","role","developer","engineer"]},{"pt":"Falou da experiência","kw":["experience","years","worked"]},{"pt":"Disse o que espera","kw":["happy","excited","glad","hope","learn"]}]$q$::jsonb,$q$A2$q$,3) on conflict (id) do update set tipo=excluded.tipo,titulo=excluded.titulo,instrucao_pt=excluded.instrucao_pt,modelo_en=excluded.modelo_en,pontos=excluded.pontos,nivel=excluded.nivel,ordem=excluded.ordem;
insert into public.fi_tarefas_escrita (id,tipo,titulo,instrucao_pt,modelo_en,pontos,nivel,ordem) values ($q$e5$q$,$q$work$q$,$q$Atualização semanal$q$,$q$Escreva um resumo da semana para seu chefe: o que terminou, o que ficou pendente e o que fará na próxima semana.$q$,$q$This week I finished the sales report and sent it to the client. I also had two meetings with the marketing team. The new website design is still in progress, and I'm waiting for feedback. Next week, I will review the feedback and start the presentation for the board.$q$,$q$[{"pt":"Disse o que terminou","kw":["finished","completed","done"]},{"pt":"Disse o que está pendente","kw":["still","in progress","pending","waiting"]},{"pt":"Disse o que fará","kw":["next week","will"]},{"pt":"Citou reunião, relatório ou retorno","kw":["report","meeting","feedback"]}]$q$::jsonb,$q$B1$q$,4) on conflict (id) do update set tipo=excluded.tipo,titulo=excluded.titulo,instrucao_pt=excluded.instrucao_pt,modelo_en=excluded.modelo_en,pontos=excluded.pontos,nivel=excluded.nivel,ordem=excluded.ordem;
