insert into public.fi_tarefas_escrita (id,tipo,titulo,instrucao_pt,modelo_en,pontos,nivel,ordem) values ($q$e7$q$,$q$travel$q$,$q$E-mail: reservar um quarto$q$,$q$Escreva para um hotel reservando um quarto de casal, de 10 a 14 de março, com café da manhã. Pergunte o preço e se há estacionamento.$q$,$q$Hello,
insert into public.fi_tarefas_escrita (id,tipo,titulo,instrucao_pt,modelo_en,pontos,nivel,ordem) values ($q$e8$q$,$q$travel$q$,$q$Reclamar de um problema no hotel$q$,$q$Você está no hotel e o ar-condicionado não funciona. Escreva uma mensagem educada pedindo para consertar ou trocar de quarto.$q$,$q$Good evening. I'm in room 305, and the air conditioning isn't working. It is very hot, and I can't sleep. Could someone fix it, please? If it's not possible, I would like to change rooms. Thank you for your help.$q$,$q$[{"pt":"Disse onde está (quarto)","kw":["room"]},{"pt":"Explicou o problema","kw":["air conditioning","not working","isn't working","broken"]},{"pt":"Pediu conserto ou troca","kw":["fix","repair","change rooms","another room"]},{"pt":"Foi educado","kw":["please","thank","could"]}]$q$::jsonb,$q$A2$q$,7) on conflict (id) do update set tipo=excluded.tipo,titulo=excluded.titulo,instrucao_pt=excluded.instrucao_pt,modelo_en=excluded.modelo_en,pontos=excluded.pontos,nivel=excluded.nivel,ordem=excluded.ordem;
insert into public.fi_tarefas_escrita (id,tipo,titulo,instrucao_pt,modelo_en,pontos,nivel,ordem) values ($q$e9$q$,$q$travel$q$,$q$Contar como foi a viagem$q$,$q$Conte a um amigo, no passado, como foi sua viagem: onde foi, o que fez e do que mais gostou.$q$,$q$Last month I traveled to Lisbon with my wife. We stayed in a small hotel near the river. Every day we walked around the city, ate fresh fish and visited old churches. I loved the trams, but my favorite part was the sunset by the sea. I want to go back next year.$q$,$q$[{"pt":"Disse para onde foi (passado)","kw":["went","traveled","visited"]},{"pt":"Disse onde ficou","kw":["stayed","hotel"]},{"pt":"Contou o que fez","kw":["ate","walked","visited","saw"]},{"pt":"Disse do que gostou","kw":["loved","favorite","enjoyed","liked"]}]$q$::jsonb,$q$B1$q$,8) on conflict (id) do update set tipo=excluded.tipo,titulo=excluded.titulo,instrucao_pt=excluded.instrucao_pt,modelo_en=excluded.modelo_en,pontos=excluded.pontos,nivel=excluded.nivel,ordem=excluded.ordem;
insert into public.fi_tarefas_escrita (id,tipo,titulo,instrucao_pt,modelo_en,pontos,nivel,ordem) values ($q$e10$q$,$q$travel$q$,$q$Pedir dicas de um lugar$q$,$q$Escreva para um amigo que mora em Londres: você vai visitar a cidade por 5 dias e quer dicas de passeios e restaurantes.$q$,$q$Hi Tom, I'm going to visit London next month for five days. Do you have any tips for places to see? I'd also like to know a good restaurant that isn't too expensive. Maybe we can meet for dinner one night. Let me know! Thanks.$q$,$q$[{"pt":"Disse que vai visitar","kw":["london","visit","going to"]},{"pt":"Disse a duração","kw":["five","5","days"]},{"pt":"Pediu dicas de passeios","kw":["tips","recommend","places","suggest"]},{"pt":"Falou de restaurante ou encontro","kw":["restaurant","dinner","meet"]}]$q$::jsonb,$q$A2$q$,9) on conflict (id) do update set tipo=excluded.tipo,titulo=excluded.titulo,instrucao_pt=excluded.instrucao_pt,modelo_en=excluded.modelo_en,pontos=excluded.pontos,nivel=excluded.nivel,ordem=excluded.ordem;
